import { DATA } from './content.js?v=e1990e019f0a';
import { createInquiry } from './inquiry.js?v=e1990e019f0a';
import { MEDIA } from './media.js?v=e1990e019f0a';
import { enhanceInterface } from './enhancements.js?v=e1990e019f0a';
import { setupComparison } from './comparison.js?v=e1990e019f0a';
const ROOT=new URL('./',import.meta.url), route=document.body.dataset.route;
const $=(s,n=document)=>n.querySelector(s), $$=(s,n=document)=>[...n.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=(p='/')=>new URL(p.replace(/^\//,''),ROOT).href;
const image=(p,alt='',cls='',eager=false)=>{const media=MEDIA[p];const variants=media?.variants||[];const src=variants.at(-1)?.src||p;return `<img src="${url(src)}" ${variants.length?`srcset="${variants.map(v=>url(v.src)+' '+v.width+'w').join(', ')}" sizes="${cls.includes('hero-image')?'(max-width: 700px) 1900px, 100vw':cls.includes('experience-image')?'900px':eager?'100vw':'(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw'}" width="${media.width}" height="${media.height}"`:''} alt="${esc(alt)}" class="${cls}" loading="${eager?'eager':'lazy'}" decoding="async"${eager?' fetchpriority="high"':''}>`;};
const ext=(href,label,cls='text-link')=>{let video='';try{const u=new URL(href);if(['www.youtube.com','youtube.com','youtu.be'].includes(u.hostname)){const id=u.hostname==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.split('/embed/')[1];if(/^[\w-]{11}$/.test(id||''))video=` data-video="${id}"`;}}catch{}return `<a href="${esc(href)}" target="_blank" rel="noopener noreferrer" class="${cls}"${video}>${String(label).replaceAll('↗',icon('arrow')).replaceAll('→',icon('arrow'))}</a>`;};
const link=(p,label,cls='',name='')=>`<a href="${url(p)}" class="${cls}"${name?' aria-label="'+esc(name)+'"':''}>${String(label).replaceAll('↗',icon('arrow')).replaceAll('→',icon('arrow'))}</a>`;
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({chevron:'<path d="m6 9 6 6 6-6"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 5a5 5 0 0 1 3 4v2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',phone:'<path d="m7 3 3 5-3 3a16 16 0 0 0 6 6l3-3 5 3c0 3-2 5-5 4C8 19 5 16 3 8 2 5 4 3 7 3Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M19 5l-1.5 1.5m-11 11L5 19"/>',waves:'<path d="M2 6q5-4 10 0t10 0M2 12q5-4 10 0t10 0M2 18q5-4 10 0t10 0"/>',tree:'<path d="m12 2 7 9h-4l6 7H3l6-7H5l7-9Zm0 16v4"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',plus:'<path d="M12 5v14M5 12h14"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 5 10 8L22 5"/>'})[name]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
const mark=`<svg viewBox="0 0 56 56" fill="none" aria-hidden="true"><path d="M13 30a15 15 0 0 1 30 0M4 36q12-8 24 0t24 0M9 44q9-6 19 0t19 0M28 2v9M7 13l7 6M49 13l-7 6" stroke="currentColor" stroke-width="1.4"/></svg>`;
const logo=()=>link('/',`${mark}<span>Тихая Гавань<small>ОТДЫХ НА ВОЛГЕ</small></span>`,'logo');
const types={cottage:'Коттедж',room:'Номер',bath:'Баня',veranda:'Веранда',event:'Мероприятие'};
const occupancy=c=>c.minGuests?'Аренда от '+c.minGuests+' гостей':(c.type==='bath'?'Для ':'До ')+c.capacity+' гостей';
const money=c=>c.price||'По запросу';
const page=path=>DATA.pages.find(p=>p.route===path);
let favorites;try{favorites=JSON.parse(localStorage.getItem('gavan:favorites')||'[]');if(!Array.isArray(favorites))favorites=[];}catch{favorites=[];}
function header(){const nav=[['/razmeshchenie/','Проживание'],['/bani/','Бани и чан'],['/meropriyatiya/','Мероприятия'],['/restoran/','Ресторан'],['/kontakty/','Контакты']];return `<div class="topbar"><div class="wrap"><span>${icon('pin')} Тольятти · полуостров Копылово</span><div><span class="topbar-welcome">Отдых на Волге круглый год</span><span class="top-social">${ext('https://t.me/tihqyagavan63','Telegram','')}${ext('https://vk.com/turbaza63','ВКонтакте','')}</span></div></div></div><header class="header"><div class="wrap header-inner">${logo()}<nav id="navigation" aria-label="Основная навигация">${nav.map(([p,t])=>`<a href="${url(p)}" ${route.startsWith(p.slice(0,-1))?'aria-current="page"':''}>${t}</a>`).join('')}<details class="nav-more"><summary>Ещё ${icon('chevron')}</summary><div>${[['/letnie-verany/','Летние веранды'],['/razmeshchenie/prajs/','Цены'],['/gallery/','Фотогалерея'],['/reviews/','Отзывы'],['/akcii/','Акции'],['/pravila/','Правила проживания']].map(([p,t])=>link(p,t)).join('')}</div></details><a href="tel:+79278925589" class="mobile-nav-phone">+7 (927) 892-55-89</a></nav><div class="header-actions"><a class="header-phone" href="tel:+79278925589">+7 (927) 892-55-89</a><button class="btn btn-small" data-inquire="Отдых в Тихой Гавани">Забронировать ${icon('arrow')}</button><button class="menu-button icon-button" aria-expanded="false" aria-controls="navigation" aria-label="Открыть меню">${icon('menu')}</button></div></div></header>`;}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top">${logo()}<p>У каждого есть место,<br>куда хочется вернуться.</p><a href="tel:+79278925589" class="footer-phone">+7 (927) 892-55-89 ${icon('arrow')}</a></div><div class="footer-columns"><div><span class="eyebrow">ПРИЕЗЖАЙТЕ В ГОСТИ</span><p>Самарская область, г. Тольятти,<br>полуостров Копылово,<br>ул. Бурлацкая, 11А</p>${link('/kontakty/','Как добраться ↗','text-link')}</div><div><span class="eyebrow">ОТДЫХ</span>${[['/razmeshchenie/kottedzhi/','Коттеджи'],['/razmeshchenie/nomera/','Гостиничные номера'],['/bani/','Бани и банный чан'],['/letnie-verany/','Веранды и беседки']].map(([p,t])=>link(p,t)).join('')}</div><div><span class="eyebrow">ПОЛЕЗНОЕ</span>${[['/razmeshchenie/prajs/','Цены и условия'],['/meropriyatiya/','Мероприятия'],['/reviews/','Отзывы гостей'],['/pravila/','Правила проживания'],['/o-baze/','О базе']].map(([p,t])=>link(p,t)).join('')}${ext('https://3d.tg63.ru/zima/3d.html','3D-тур ↗','')}</div><div><span class="eyebrow">МЫ НА СВЯЗИ</span><a href="tel:+79272191586">+7 (927) 219-15-86</a><a href="tel:+78482625589">+7 (8482) 62-55-89</a><a href="mailto:turbaza63@yandex.ru">turbaza63@yandex.ru</a><div class="social-links">${ext('https://t.me/tihqyagavan63','Telegram ↗','')}${ext('https://vk.com/turbaza63','VK ↗','')}${ext('https://wa.me/79272191586','WhatsApp ↗','')}${ext('https://ok.ru/group/51798118826177','ОК ↗','')}${ext('https://www.instagram.com/turbaza63.samara/','Instagram ↗','')}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} «Тихая Гавань»</span>${link('/politika-konfidenczialnosti/','Конфиденциальность')}</div><p class="footer-note">Наличие мест и стоимость на выбранные даты уточняйте при бронировании.</p></div></footer><button class="to-top icon-button" aria-label="Вернуться наверх">${icon('arrow')}</button>`;}
function card(c){return `<article class="stay-card"><div class="card-visual">${link(c.route+'/',image(c.cover||DATA.images.hero,c.title))}<span class="tag">${types[c.type]}</span>${['room','cottage'].includes(c.type)?`<button class="favorite icon-button ${favorites.includes(c.route)?'is-saved':''}" data-favorite="${c.route}" aria-label="${favorites.includes(c.route)?'Убрать из избранного':'В избранное'}: ${esc(c.title)}" aria-pressed="${favorites.includes(c.route)}">${icon('heart')}</button>`:''}</div><div class="card-content"><div class="card-meta">${c.capacity||c.minGuests?`${icon('people')} ${occupancy(c)}`:'По предварительной записи'}<span>Тихая Гавань</span></div><h3>${link(c.route+'/',esc(c.title.replace(/^Коттедж |^Веранда /,'')))}</h3><div class="card-bottom"><div><strong>${money(c)}</strong><small>${c.priceUnit|| (c.price?'стоимость уточняется на ваши даты':'Условия уточняйте')}</small></div>${link(c.route+'/',icon('arrow'), 'circle-link','Подробнее: '+c.title)}</div>${['room','cottage'].includes(c.type)?`<button type="button" class="compare-toggle" data-compare="${esc(c.route)}" aria-pressed="false" aria-label="Сравнить: ${esc(c.title)}">Сравнить вариант</button>`:''}</div></article>`;}
function sectionHead(eyebrow,title,more,href){return `<div class="section-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${more?link(href,`${more} ${icon('arrow')}`,'text-link'):''}</div>`;}
function searchForm(){return `<form class="search-panel" id="stay-search"><div class="search-title"><span class="eyebrow">ВАШ МАЛЕНЬКИЙ ОТПУСК</span><strong>Когда приедете?</strong></div><label>${icon('calendar')}<span>Заезд<input type="date" name="arrival" aria-label="Дата заезда"></span></label><label>${icon('calendar')}<span>Выезд<input type="date" name="departure" aria-label="Дата выезда"></span></label><label>${icon('people')}<span>Гости<select name="guests" aria-label="Количество гостей">${[2,1,3,4,5,6,8,10,12,16,18].map(n=>`<option value="${n}">${n} ${n===1?'гость':n<5?'гостя':'гостей'}</option>`).join('')}</select></span></label><button class="btn">Найти свой дом ${icon('arrow')}</button><p class="form-error" aria-live="polite"></p></form>`;}
const faq=()=>`<div class="faq"><details><summary>Во сколько заезд и выезд? ${icon('plus')}</summary><p>Заезд с 16:00, выезд до 14:00. Возможность другого времени согласуйте с администратором.</p></details><details><summary>Можно ли приехать с питомцем? ${icon('plus')}</summary><p>Размещение с животными не предусмотрено.</p></details><details><summary>Нужно ли брать принадлежности для мангала? ${icon('plus')}</summary><p>Решётку и шампуры можно привезти с собой. Возможность аренды и стоимость уточните у администратора.</p></details><details><summary>Как узнать стоимость на мои даты? ${icon('plus')}</summary><p>Выберите объект и подготовьте заявку с датами и количеством гостей. Администратор уточнит наличие, итоговую стоимость и условия бронирования.</p></details></div>`;
function home(){const chosen=['/razmeshchenie/kottedzhi/domik-na-volge','/razmeshchenie/kottedzhi/semejnyj','/razmeshchenie/kottedzhi/belyj-dom'];const stays=chosen.map(r=>DATA.catalog.find(c=>c.route===r));const wedding=DATA.catalog.find(c=>c.route==='/letnie-verany/letnyaya-veranda-svadebnaya');return `<section class="hero">${image(DATA.images.hero,'Территория турбазы «Тихая Гавань»','hero-image',true)}<div class="hero-shade"></div><div class="wrap hero-inner"><div class="hero-kicker"><span class="line"></span> ПРИРОДА. ВОЛГА. ВАШЕ ВРЕМЯ.</div><h1>Ближе к природе.<br>Ближе к <em>себе.</em></h1><p>Срубовые дома, тёплые встречи и неспешные<br class="desktop"> дни на берегу Волги. Здесь хорошо быть вместе.</p><div class="hero-buttons">${link('/razmeshchenie/','Выбрать проживание '+icon('arrow'),'btn btn-cream')}${link('/gallery/','Почувствовать атмосферу','hero-text-link')}</div>${ext('https://3d.tg63.ru/zima/3d.html',`<span>360°</span><small>ОГЛЯНИТЕСЬ<br>ВОКРУГ</small>${icon('arrow')}`,'tour-link')}<div class="hero-bottom"><span>${icon('pin')} ПОЛУОСТРОВ КОПЫЛОВО · ТОЛЬЯТТИ</span><span>ОТДЫХ В ЛЮБОЕ ВРЕМЯ ГОДА <span class="scroll-line"></span></span></div></div></section><div class="wrap search-wrap">${searchForm()}</div><section class="section wrap intro"><div><span class="eyebrow">ТИХАЯ ГАВАНЬ — ЭТО СОСТОЯНИЕ</span><h2>Здесь можно<br>никуда <em>не спешить.</em></h2></div><div class="intro-copy"><p>Просыпаться среди деревьев. Смотреть, как меняется Волга. Собраться за одним столом с теми, кто дорог.</p><p class="muted">На полуострове Копылово есть место и для тихого семейного выходного, и для большого праздника. Выбирайте свой ритм — остальное подождёт.</p>${link('/kontakty/','Найти свою гавань '+icon('arrow'),'text-link')}</div></section><div class="wrap fact-row"><div>${icon('waves')}<span>На берегу<br><strong>Волги</strong></span></div><div>${icon('tree')}<span>Среди деревьев<br><strong>Копылово</strong></span></div><div>${icon('people')}<span>Для семьи<br><strong>и друзей</strong></span></div><div>${icon('sun')}<span>В любое<br><strong>время года</strong></span></div></div><section class="section soft-section"><div class="wrap">${sectionHead('ОСТАТЬСЯ ПОДОЛЬШЕ','Дом, в котором<br>хочется <em>остаться.</em>','Весь каталог','/razmeshchenie/')}<div class="home-catalog-tabs" role="group" aria-label="Тип проживания"><button class="pill active" data-home-type="cottage" aria-pressed="true">Коттеджи</button><button class="pill" data-home-type="room" aria-pressed="false">Гостиничные номера</button><span>У каждого дома — своя история</span></div><div class="card-grid" id="home-stays">${stays.map(card).join('')}</div><p class="price-note">* Стоимость зависит от дат и состава гостей. Уточните окончательную цену при бронировании. ${link('/razmeshchenie/prajs/','Посмотреть прайс →')}</p></div></section><section class="section wrap">${sectionHead('ОТДЫХ В ВАШЕМ РИТМЕ','Делать то,<br>что <em>по душе.</em>','Все возможности','/meropriyatiya/')}<div class="experience-grid">${[['/bani/','Пар, дерево<br>и полное спокойствие','БАНИ И БАННЫЙ ЧАН',DATA.catalog.find(c=>c.route==='/bani/banya-provans')?.cover],['/restoran/','Вкусные моменты<br>в хорошей компании','РЕСТОРАН',DATA.images.restaurant],['/letnie-verany/','Длинный день<br>у большой воды','ВЕРАНДЫ И БЕСЕДКИ',DATA.images.river],['/gallery/','Лето, которое<br>хочется продлить','БАССЕЙН И ТЕРРИТОРИЯ',DATA.images.pool]].map(([p,t,k,im])=>link(p,`${image(im,k,'experience-image')}<div><span class="eyebrow">${k}</span><h3>${t}</h3><span class="experience-arrow">${icon('arrow')}</span></div>`,'experience-card')).join('')}</div></section><section class="celebration"><div class="wrap celebration-grid"><div><span class="eyebrow">БОЛЬШИЕ ПОВОДЫ. ТЁПЛЫЕ ВСТРЕЧИ.</span><h2>Важный день.<br><em>Ваши люди.</em><br>Красивое место.</h2><p>Свадьба на берегу, день рождения среди друзей или встреча всей команды. Соберём повод, место и настроение в один незабываемый день.</p>${link('/meropriyatiya/','Спланировать событие '+icon('arrow'),'btn btn-cream')}<div class="occasion-links">${link('/meropriyatiya/svadby/','Свадьбы ↗')}${link('/meropriyatiya/korporativnye-meropriyatiya/','Корпоративы ↗')}${link('/meropriyatiya/dni-rozhdeniya-yubilei/','Дни рождения ↗')}</div></div><div class="celebration-photo">${image(wedding.cover,'Свадебное оформление веранды на турбазе')}<span class="photo-caption">МЕСТО ДЛЯ ВАШЕЙ НОВОЙ ИСТОРИИ</span></div></div></section><section class="section wrap">${sectionHead('ЧЕРЕЗ ОБЪЕКТИВ','Уже хочется <em>сюда.</em>','Все фотографии','/gallery/')}<div class="mosaic">${[DATA.images.river,DATA.images.gallery[0],DATA.images.pool].map((im,i)=>`<button class="gallery-open" data-gallery="home" data-index="${i}" aria-label="Посмотреть фотографию ${i+1}">${image(im,['Терраса над Волгой','Срубовый коттедж','Бассейн на территории'][i])}${icon('expand')}</button>`).join('')}</div></section><section class="section soft-section"><div class="wrap reviews-home">${sectionHead('СЛОВА, КОТОРЫЕ ГРЕЮТ','Сюда <em>возвращаются.</em>','Отзывы гостей','/reviews/')}<div class="review-grid">${reviewCards(3)}</div></div></section><section class="section wrap faq-grid"><div><span class="eyebrow">ПЕРЕД ПОЕЗДКОЙ</span><h2>Всё, что<br>хочется <em>знать.</em></h2><p class="muted">Остались вопросы? Мы рядом.</p><a href="tel:+79278925589" class="text-link">+7 (927) 892-55-89 ${icon('arrow')}</a></div>${faq()}</section>${contactStrip()}`;}
const reviewSummaries=[{"name": "Дарья Бочкарева", "date": "11 февраля 2024", "text": "Сотрудники помогли быстро организовать юбилей для большой компании. Гостям запомнились тёплый приём, природа и зимние развлечения для детей.", "more": "Встреча состоялась после неожиданной отмены в другом месте. Администрация помогла с размещением и подготовкой праздника.", "reply": "Администрация поблагодарила гостей и пригласила их приехать снова.", "avatar": "assets/review-745b145c9a.jpg"}, {"name": "Анна", "date": "5 декабря 2023", "text": "Анна отметила внимательную помощь при бронировании, заботу во время проживания и вкусную еду в ресторане.", "more": "После поездки гости решили вернуться на зимние каникулы.", "reply": "Администрация поблагодарила Анну за отзыв.", "avatar": null}, {"name": "Елена Зенова", "date": "21 июля 2022", "text": "Семье понравились чистота дома, удобные матрасы и оснащение комнат. Елена также отметила шум от соседей поздним вечером.", "more": "Гости отдыхали несколькими поколениями. В ответе администрация пообещала обсудить замечание с дежурными сотрудниками.", "reply": "Администрация приняла замечание о соблюдении тишины.", "avatar": "assets/review-2681b3f215.jpg"}, {"name": "Анастасия Шишова", "date": "21 июля 2022", "text": "Зимняя поездка по подарочному сертификату запомнилась заботой сотрудников, катком и русской баней.", "more": "Анастасия особенно оценила одинаково внимательное отношение ко всем гостям.", "reply": "Администрация поблагодарила за подробные впечатления.", "avatar": "assets/review-b966f647d6.jpg"}, {"name": "Dmitriy Yushin", "date": "21 июля 2022", "text": "Дмитрий отметил вид на Волгу, просторную беседку и внимательную работу сотрудников.", "more": "Особенно гостям понравилось размещение в доме у воды.", "reply": "Администрация передала благодарность сотрудникам.", "avatar": "assets/review-ae085aef37.jpg"}, {"name": "Алена Тарзилова", "date": "21 июля 2022", "text": "Алёне понравились продуманные детали дома, питание и отзывчивость персонала. Состояние велосипедов в прокате она оценила критически.", "more": "Впечатление от отдыха в целом осталось хорошим.", "reply": "Администрация поблагодарила за обратную связь.", "avatar": "assets/review-12098a7a4c.jpg"}];
function reviewCards(n=99){return reviewSummaries.slice(0,n).map((r,i)=>`<article class="review-card" id="guest-review-${i}"><div class="review-person">${r.avatar?image(r.avatar,r.name,'avatar'):`<span class="avatar" aria-hidden="true">${r.name[0]}</span>`}<div><strong>${r.name}</strong><small>${r.date}</small></div></div><p>${r.text}</p><details class="review-details"><summary>Подробнее об отдыхе ${icon('plus')}</summary><p>${r.more}</p><div class="admin-reply"><strong>Ответ администрации</strong><p>${r.reply}</p></div></details></article>`).join('');}
function contactStrip(){return `<section class="contact-strip"><div class="wrap"><div><span class="eyebrow">ВАША ГАВАНЬ УЖЕ РЯДОМ</span><h2>Давайте устроим<br><em>ваш хороший день.</em></h2></div><div><button class="btn btn-cream" data-inquire="Помогите подобрать отдых">Помогите с выбором ${icon('arrow')}</button><a href="tel:+79278925589">или позвоните: +7 (927) 892-55-89</a></div></div></section>`;}
function breadcrumb(name,parent){return `<div class="wrap breadcrumbs">${link('/','Главная')}<span>/</span>${parent?`${link(parent[0],parent[1])}<span>/</span>`:''}<span>${esc(name)}</span></div>`;}
function pageHeading(kicker,title,description=''){return `<div class="page-heading wrap"><span class="eyebrow">${kicker}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`;}
function catalogPage(type){const name=type==='room'?'Гостиничные номера':type==='cottage'?'Коттеджи':'Проживание';return `${breadcrumb(name)}${pageHeading('ВАШ ДОМ У ВОЛГИ',type==='room'?'Гостиничные <em>номера.</em>':type==='cottage'?'Ваш <em>коттедж.</em>':'Дома и <em>номера.</em>','От номера для двоих до дома для большой компании. Выберите по вместимости и стоимости.')}<section class="wrap catalog-section"><form id="catalog-filters" class="catalog-filters"><div class="filter-type" role="group" aria-label="Тип проживания">${[['all','Всё проживание'],['cottage','Коттеджи'],['room','Номера']].map(([v,t])=>`<button type="button" data-type="${v}" class="pill ${(type||'all')===v?'active':''}" aria-pressed="${(type||'all')===v}">${t}</button>`).join('')}</div><div class="filter-controls"><label class="filter-search">${icon('search')}<input name="search" aria-label="Поиск по названию" placeholder="Название дома или номера"></label><label>Гостей<select name="guests" aria-label="Вместимость"><option value="0">Любое число</option>${[2,4,6,8,10,12,16,18].map(n=>`<option value="${n}">От ${n} гостей</option>`).join('')}</select></label><label>Сортировка<select name="sort" aria-label="Сортировка"><option value="default">Рекомендуем</option><option value="price-asc">Сначала дешевле</option><option value="price-desc">Сначала дороже</option><option value="capacity">Больше гостей</option></select></label></div><div class="filter-bottom"><span id="catalog-count" aria-live="polite"></span><label class="check-line"><input type="checkbox" name="saved"> ${icon('heart')} Только избранное</label><button class="text-button" type="reset">Сбросить фильтры</button></div></form><div id="date-context" class="context-note" hidden></div><div class="card-grid catalog-grid" id="catalog-results"></div><p class="price-note">* Итоговую стоимость и наличие мест на выбранные даты подтвердит администратор.</p></section>${contactStrip()}`;}
function groupPage(type){const isBath=type==='bath',isEvent=type==='event';const data=DATA.catalog.filter(c=>c.type===type);const title=isBath?'Бани и банный чан':isEvent?'Мероприятия':'Летние веранды';return `${breadcrumb(title)}${pageHeading(isBath?'ТЕПЛО, КОТОРОЕ ОСТАЁТСЯ':isEvent?'СОБРАТЬ ТЕХ, КТО ДОРОГ':'БОЛЬШЕ ВОЗДУХА. БОЛЬШЕ ВОЛГИ.',isBath?'Выдохнуть.<br><em>И согреться.</em>':isEvent?'Для любого повода.<br><em>Для ваших людей.</em>':'Ваш день<br><em>на свежем воздухе.</em>',isBath?'Русский пар, отдых в бане и банный чан. Выберите свой способ замедлиться.':isEvent?'От семейного праздника до встречи команды. Выберите формат — обсудим детали, площадку и размещение.':'Террасы у воды, беседки и площадки для встреч. Сезон работы, вместимость и условия аренды уточняйте перед поездкой.')}<section class="wrap section-top-small"><div class="card-grid ${isEvent?'event-grid':''}">${data.map(card).join('')}</div><p class="price-note">${isEvent?'Состав программы и возможность проведения активностей подтверждает администрация.':'Стоимость на вашу дату и условия посещения уточняйте у администратора.'}</p></section>${contactStrip()}`;}
function detail(c){const isStay=['cottage','room'].includes(c.type),isEvent=c.type==='event';const parent=isStay?['/razmeshchenie/','Проживание']:c.type==='bath'?['/bani/','Бани и чан']:c.type==='veranda'?['/letnie-verany/','Веранды']:['/meropriyatiya/','Мероприятия'];const photos=c.photos?.length?c.photos:[c.cover||DATA.images.hero];const displayTitle=c.title.replace(/^Коттедж |^Веранда /,'');return `${breadcrumb(displayTitle,parent)}<section class="detail-title wrap"><div><span class="eyebrow">${types[c.type].toUpperCase()} · ТИХАЯ ГАВАНЬ</span><h1>${esc(displayTitle)}</h1></div>${c.capacity||c.minGuests?`<span class="capacity-badge">${icon('people')} ${occupancy(c)}</span>`:''}</section><section class="detail-gallery wrap ${photos.length<3?'few-photos':''}">${photos.slice(0,3).map((im,i)=>`<button class="gallery-open photo-${i}" data-gallery="detail" data-index="${i}" aria-label="Открыть фото ${i+1}: ${esc(c.title)}">${image(im,c.title+' — фото '+(i+1),'',true)}${i===2?`<span class="all-photos">${icon('expand')} Все фото · ${photos.length}</span>`:''}</button>`).join('')}${photos.length<3?`<button class="gallery-all btn btn-cream" data-gallery="detail" data-index="0">${icon('expand')} Фотографии · ${photos.length}</button>`:''}</section><section class="wrap detail-layout"><div><div class="detail-tabs"><a href="#description">Описание</a><a href="#conditions">Условия</a>${ext('https://3d.tg63.ru/zima/3d.html','3D-тур ↗','')}</div><div class="detail-description" id="description"><span class="eyebrow">ПРОСТРАНСТВО ДЛЯ ОТДЫХА</span><h2>${isEvent?'Ваш повод —<br><em>наша площадка.</em>':isStay?'Здесь будет<br><em>по-домашнему.</em>':'Время для<br><em>вашего отдыха.</em>'}</h2>${isEvent?`<p>${eventCopy(c.route)}</p><p class="muted">Оставьте пожелания, дату и количество гостей. Администратор расскажет о возможных площадках, программе и стоимости.</p>`:`<ul class="description-list">${(c.description?.length?c.description:['Условия посещения и подробности об объекте уточняйте у администратора.']).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`}${c.services?.length?`<div class="amenities">${c.services.map(t=>`<div>${icon('check')}<span>${esc(t)}</span></div>`).join('')}</div>`:''}</div><div id="conditions" class="conditions"><h3>Полезно перед поездкой</h3>${isStay?`<div class="check-times"><div>${icon('calendar')}<span>Заезд<strong>с 16:00</strong></span></div><div>${icon('calendar')}<span>Выезд<strong>до 14:00</strong></span></div></div><p>Проживание с животными запрещено. Дополнительные услуги, питание, парковочные места и ранний заезд согласуются с администрацией.</p>`:`<p>Дата, продолжительность, состав услуг и окончательная стоимость согласуются с администрацией. Сезонные активности зависят от погоды и доступности.</p>`}${link('/pravila/','Правила пребывания '+icon('arrow'),'text-link')}<div class="detail-external">${c.video?.[0]?ext(c.video[0].replace('/embed/','/watch?v='),'Видео об объекте ↗'):''}</div></div></div><aside class="booking-card"><span class="eyebrow">${isStay?'ВАШ МАЛЕНЬКИЙ ОТПУСК':'ДАВАЙТЕ СПЛАНИРУЕМ'}</span><div class="detail-price"><strong>${money(c)}</strong></div><p class="muted small">${c.priceUnit?esc(c.priceUnit)+'. ':''}${c.price?'Итоговая стоимость зависит от дат и количества гостей.':'Стоимость и условия — у администратора.'}</p><button class="btn" data-inquire="${esc(c.title)}">${isStay?'Уточнить даты и стоимость':'Обсудить детали'} ${icon('arrow')}</button>${isStay?ext('https://gavan.tg63.ru/','Перейти к бронированию ↗','booking-system'):''}<div class="booking-phone"><span>Поможем с выбором</span><a href="tel:+79278925589">${icon('phone')} +7 (927) 892-55-89</a></div>${c.priceRows?.length?`<details class="tariffs"><summary>Тарифы и дополнительные услуги</summary>${c.priceRows.map(p=>`<div><span>${esc(p.label)}</span><strong>${esc(p.value)}</strong></div>`).join('')}<small>Не являются подтверждённой стоимостью бронирования.</small></details>`:''}${isStay?ext('https://secure-payment-gateway.ru/sc/TwgRQcJBAPHEGxVA','Оплата подтверждённой брони ↗','payment-link'):''}</aside></section><section class="soft-section section"><div class="wrap">${sectionHead('ЕЩЁ НЕМНОГО ВДОХНОВЕНИЯ',isStay?'Другие <em>варианты.</em>':'Посмотрите <em>также.</em>','Весь раздел',parent[0])}<div class="card-grid">${DATA.catalog.filter(x=>x.type===c.type&&x.route!==c.route).slice(0,3).map(card).join('')}</div></div></section>`;}
function eventCopy(r){const text={svadby:'Веранды, ресторан и берег Волги — для церемонии, банкета и встречи самых близких. На базе можно обсудить размещение гостей после праздника.', 'korporativnye-meropriyatiya':'Встреча команды за городом: общение, банкет и совместный отдых. Формат и программу можно согласовать с администрацией.',vypusknye:'Выпускной на природе с банкетом и общей программой. Обсудите подходящую площадку, количество гостей и организационные детали.','detskie-prazdniki':'Детский праздник за городом: площадки на территории, активные игры и время всей семьёй. Возраст участников и программу согласуйте заранее.','dni-rozhdeniya-yubilei':'Соберите близких на день рождения или юбилей. На территории есть коттеджи, ресторан, веранды и беседки для разных форматов встречи.','konferenczii-seminary-treningi-obucheniya':'Деловые встречи и обучение в загородной обстановке. Уточните оснащение конференц-зала, питание и варианты размещения участников.','pejntbol-lazertag-gidrobol':'Командные игры на свежем воздухе. Наличие оборудования, возраст участников и формат игры согласуйте с администратором.',kvesty:'Командные квесты и игровые программы на природе. Сценарий, продолжительность и состав группы обсуждаются заранее.','organizacziya-master-klassov':'Творческая встреча или мастер-класс для вашей компании. Тему, ведущего, материалы и площадку необходимо согласовать заранее.','uroki-verhovoj-ezdy':'Занятия верховой ездой. Уточните возможность проведения, место встречи и требования к участникам.','kataniya-na-bajdarkah-i-kanoe':'Прогулки по воде на байдарках и каноэ представлены среди активностей базы. Сезон, маршрут и сопровождение уточняйте заранее.',veloprokat:'Велопрогулки по полуострову Копылово. Наличие велосипедов, маршруты и условия проката уточняйте перед приездом.','vyezdnaya-rybalka-arenda-katera':'Рыбалка и прогулки на катере по Волге. Обсудите маршрут, продолжительность и возможность выхода на воду.',pokatushki:'Водные прогулки и развлечения на Волге.'};return text[r.split('/').pop()]||'Отдых на Волге для вашей компании. Актуальные возможности, сезон работы и условия участия уточните у администратора.';}
function restaurant(){const p=page('/restoran');return `${breadcrumb('Ресторан')}${pageHeading('ХОРОШО, КОГДА ВСЕ ЗА ОДНИМ СТОЛОМ','Со вкусом.<br><em>С видом на Волгу.</em>','Завтрак перед прогулкой, семейный обед или банкет в честь важного дня.')}<div class="wrap restaurant-visual">${image(DATA.images.restaurant,'Сервировка ресторана «Тихая Гавань»','',true)}<span>РЕСТОРАН «ТИХАЯ ГАВАНЬ»</span></div><section class="section wrap editorial-grid"><div><span class="eyebrow">ОТ ПРОСТОГО ДО ПРАЗДНИЧНОГО</span><h2>У встречи есть<br><em>свой вкус.</em></h2></div><div><p>В ресторане есть уютный зал, бар и банкетный зал с панорамными окнами. Питание и обслуживание мероприятий можно обсудить заранее.</p><p class="muted">Меню, часы работы и стоимость питания уточняйте перед поездкой. Состав меню и стоимость обслуживания согласуем под ваш повод и количество гостей.</p><div class="button-row"><button class="btn" data-inquire="Ресторан и банкет">Обсудить банкет ${icon('arrow')}</button>${link('/menu/','Посмотреть меню ↗','text-link')}</div></div></section><section class="wrap section-top-small"><div class="mosaic">${p.photos.slice(1,4).map((im,i)=>`<button class="gallery-open" data-gallery="restaurant" data-index="${i+1}" aria-label="Интерьер ресторана, фото ${i+2}">${image(im,'Ресторан, интерьер')}${icon('expand')}</button>`).join('')}</div></section>${contactStrip()}`;}
function pricing(){const all=DATA.catalog.filter(c=>['cottage','room'].includes(c.type));const sub=page(route);return `${breadcrumb('Цены и условия')}${pageHeading('ПЛАНИРУЙТЕ СВОЙ ОТДЫХ','Понятно о <em>стоимости.</em>','Итоговая цена зависит от объекта, дат и состава гостей. Свободные даты и стоимость подтверждаются администратором.')}<section class="wrap section-top-small"><div class="notice">${icon('calendar')}<div><strong>Цены требуют уточнения</strong><p>Цены в каталоге помогут сориентироваться. Для точного расчёта укажите даты и количество гостей.</p></div><button class="btn btn-small" data-inquire="Расчёт стоимости проживания">Получить расчёт ${icon('arrow')}</button></div><div class="price-table-wrap"><table class="price-table"><thead><tr><th>Проживание</th><th>Гостей</th><th>Цена из каталога*</th><th><span class="sr-only">Подробнее</span></th></tr></thead><tbody>${all.map(c=>`<tr><td>${link(c.route+'/',esc(c.title))}<small>${types[c.type]}</small></td><td>до ${c.capacity}</td><td>${c.price||'Уточнить'}</td><td>${link(c.route+'/',icon('arrow'),'circle-link','Подробнее: '+c.title)}</td></tr>`).join('')}</tbody></table></div><p class="price-note">* Итоговая стоимость зависит от дат, длительности поездки и количества гостей.</p><div class="archive-section"><span class="eyebrow">СЕЗОННЫЕ ПРЕДЛОЖЕНИЯ</span><h2>Сезонные <em>прайсы.</em></h2><p class="muted">Архивные таблицы сохранены для ознакомления. Период действия и актуальность уточняйте.</p><div class="archive-links">${DATA.pages.filter(p=>p.route.startsWith('/razmeshchenie/prajs/')).map(p=>link(p.route+'/',`${esc(p.title)} ${icon('arrow')}`,route===p.route?'active':'')).join('')}</div>${route!=='/razmeshchenie/prajs'&&sub?`<h3>${esc(sub.title)} · архив</h3>${sub.period?`<p class="price-note">Период действия: ${esc(sub.period)}</p>`:''}${sub.tables.length?sub.tables.map((table,i)=>`<details class="archive-table" ${i===0?'open':''}><summary>${esc(sub.tableTitles?.[i]||`Тарифы · раздел ${i+1}`)} ⌄</summary><div class="price-table-wrap"><table class="price-table">${table.map((row,i)=>`<tr>${row.map(v=>`<${i?'td':'th'}>${esc(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table></div></details>`).join(''):`<p>Условия уточняйте у администратора.</p>`}`:''}</div></section>${contactStrip()}`;}
function galleryPage(){return `${breadcrumb('Фотогалерея')}${pageHeading('БЕЗ ЛИШНИХ СЛОВ','Почувствуйте <em>место.</em>','Территория, дома, интерьеры и берег Волги. ')}<section class="wrap section-top-small"><div class="gallery-filter" role="group" aria-label="Категория фотографий">${[['all','Вся база'],['cottage','Коттеджи'],['bath','Бани'],['veranda','Веранды']].map(([v,t])=>`<button class="pill ${v==='all'?'active':''}" data-photo-type="${v}" aria-pressed="${v==='all'}">${t}</button>`).join('')}</div><div class="photo-grid" id="photo-grid"></div></section>${contactStrip()}`;}
